<script setup>
import { computed } from "vue";
import VPSponsorsGrid from "./VPSponsorsGrid.vue";
const props = defineProps({
	mode: {
		type: String,
		required: false,
		default: "normal"
	},
	tier: {
		type: String,
		required: false
	},
	size: {
		type: String,
		required: false
	},
	data: {
		type: Array,
		required: true
	}
});
const sponsors = computed(() => {
	const isSponsors = props.data.some((s) => {
		return "items" in s;
	});
	if (isSponsors) {
		return props.data;
	}
	return [{
		tier: props.tier,
		size: props.size,
		items: props.data
	}];
});
</script>

<template>
  <div class="VPSponsors vp-sponsor" :class="[mode]">
    <section
      v-for="(sponsor, index) in sponsors"
      :key="index"
      class="vp-sponsor-section"
    >
      <h3 v-if="sponsor.tier" class="vp-sponsor-tier">{{ sponsor.tier }}</h3>
      <VPSponsorsGrid :size="sponsor.size" :data="sponsor.items" />
    </section>
  </div>
</template>
